/// Typed accessors, one per key, in the current locale ([appLocale]).
abstract final class S {
  /// account must be "observer" or "main"
  static String get apiErrorAccountObserverMain => t('api.error.accountObserverMain');
  /// account must be "observer", "main" or "all"
  static String get apiErrorAccountObserverMainAll => t('api.error.accountObserverMainAll');
  /// {count} friends have this name: use the nsaId
  static String apiErrorAmbiguousTarget({required num count}) => t('api.error.ambiguousTarget', {'count': count});
  /// bad host
  static String get apiErrorBadHost => t('api.error.badHost');
  /// request body too large
  static String get apiErrorBodyTooLarge => t('api.error.bodyTooLarge');
  /// could not save the consent
  static String get apiErrorConsentWriteFailed => t('api.error.consentWriteFailed');
  /// diagnostics already ran recently
  static String get apiErrorDiagnosticsTooSoon => t('api.error.diagnosticsTooSoon');
  /// expected {"accepted": true}
  static String get apiErrorExpectedAccepted => t('api.error.expectedAccepted');
  /// expected {"enabled": true|false}
  static String get apiErrorExpectedEnabled => t('api.error.expectedEnabled');
  /// {field} is required
  static String apiErrorFieldRequired({required Object field}) => t('api.error.fieldRequired', {'field': field});
